import React, {useState} from 'react';
import './css/Sub02.scss';
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {faShoppingCart} from "@fortawesome/free-solid-svg-icons";
import premium1 from './images/sub02_product1.jpg';
import premium2 from './images/sub02_product2.jpg';
import premium3 from './images/sub02_product3.jpg';
import premium4 from './images/sub02_product4.png';

function Sub02() {

    const [premium] = useState([
        {
            premiumTitle : "파인애플 델몬트",
            premiumOriginalPrice : "12000",
            premiumPrice : "9000",
            premiumPercent : "30%",
            premiumImgSpace : premium1
        },
        {
            premiumTitle : "바나나 스위트",
            premiumOriginalPrice : "321",
            premiumPrice : "1000",
            premiumPercent : "411",
            premiumImgSpace : premium2
        },
        {
            premiumTitle : "사과 맛있어",
            premiumOriginalPrice : "123",
            premiumPrice : "321",
            premiumPercent : "132",
            premiumImgSpace : premium3
        },
        {
            premiumTitle : "배 크다",
            premiumOriginalPrice : "123",
            premiumPercent : "321",
            premiumPrice : "231",
            premiumImgSpace : premium4
        }
    ]);
    return (
        <>
            <article className="premiumProduct">
                <h4>🌳프리미엄 헤어케어 르네휘테르</h4>
                <p>10만원 이상 구매 시 포티샤 샴푸 250mL 증정</p>
                <ul>
                    {premium.map((item) => (
                        <li className="premium" key={item.premiumTitle}>
                            <div className="imgSpace">
                                <img src={item.premiumImgSpace} alt="Product1"/>
                            </div>
                            <div className="premiumCart"><button><FontAwesomeIcon icon={faShoppingCart} /> 담기</button></div>
                            <div className="premiumInfo">
                                <span className="premiumTitle">{item.premiumTitle}</span>
                                <p className="premiumOriginalPrice">{item.premiumOriginalPrice}</p>
                                <p className="premiumPercent">{item.premiumPercent}<span className="premiumPrice">{item.premiumPrice}</span></p>
                            </div>
                        </li>
                    ))}
                </ul>
            </article>
        </>
    );
}

export default Sub02;