import React from 'react';
import './css/Join.scss';
import searchIcon from './images/searchIcon.svg';
function Join() {
    return (
        <>
            <section className="join">
                <h2>회원가입</h2>
                <div className="joinForm">
                    <div className="reqDiv">
                        <span className="req"/>필수입력사항
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">아이디<span className="req"/></div>
                        <div className="joinDesc"><input type="text" className="jTextBox" placeholder="아이디를 입력해 주세요."/></div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">비밀번호<span className="req"/></div>
                        <div className="joinDesc"><input type="text" className="jTextBox" placeholder="비밀번호를 입력해 주세요."/></div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">비밀번호 확인<span className="req"/></div>
                        <div className="joinDesc"><input type="text" className="jTextBox" placeholder="비밀번호를 한번 더 입력해 주세요."/></div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">이름<span className="req"/></div>
                        <div className="joinDesc"><input type="text" className="jTextBox" placeholder="이름을 입력해 주세요."/></div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">이메일<span className="req"/></div>
                        <div className="joinDesc">
                            <input type="text" className="jEmailBox" placeholder="이메일을 입력해 주세요."/>
                            <span className="emailSpan">@</span>
                            <select className="jEmailSelect">
                                <option value="naver.com">naver.com</option>
                                <option value="gmail.com">gmail.com</option>
                                <option value="daum.net">daum.net</option>
                                <option value="nate.com">nate.com</option>
                                <option value="hotmail.com">hotmail.com</option>
                                <option value="etc">직접입력</option>
                            </select>
                        </div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">휴대폰 번호<span className="req"/></div>
                        <div className="joinDesc"><input type="text" className="jTextBox" placeholder="숫자만 입력해 주세요."/></div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">주소<span className="req"/></div>
                        <div className="joinDesc">
                            <button className="jTextBox">
                                <img src={searchIcon} alt=""/><span>주소검색</span>
                            </button>
                            <p className="addressInfo">배송지에 따라 상품정보가 달라질 수 있습니다.</p>
                        </div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">성별<span className="req"/></div>
                        <div className="joinRadioGroup">
                            <label className="joinRadio" for="gender-man">
                                <input id="gender-man" type="radio" value="MALE" name="gender" className="radioBtn"/>
                                <span className="">남자</span>
                            </label>
                            <label className="joinRadio" for="gender-woman">
                                <input id="gender-woman" type="radio" value="FEMALE" name="gender" className="radioBtn"/>
                                <span className="">여자</span>
                            </label>
                            <label className="joinRadio" for="gender-none">
                                <input id="gender-none" type="radio" value="NONE" name="gender" className="radioBtn" checked/>
                                <span className="">선택안함</span>
                            </label>
                        </div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">생년월일<span className="req"/></div>
                        <div className="joinDesc">
                            <input type="text" className="jBirthBox txt1" placeholder="YYYY"/><span className="slash">/</span>
                            <input type="text" className="jBirthBox txt2" placeholder="MM"/><span className="slash">/</span>
                            <input type="text" className="jBirthBox txt3" placeholder="DD"/>
                        </div>
                    </div>
                    <div className="inputForm">
                        <div className="joinTitle">추가입력사항<span className="req"/></div>
                    </div>
                </div>
                <div className="">
                    <div className="">
                        <label className="" for="TermsAgreeAll">
                            <input id="TermsAgreeAll" className="" type="checkbox"/>
                            <span>전체 동의합니다</span>
                        </label>
                        <p className="">선택 항목에 동의하지 않은 경우도 회원가입 및 일반적인 서비스를 이용할 수 있습니다.</p></div>
                        <div className="">
                            <div className="">
                                <label className="" for="RequiredTermsCondition">
                                    <input id="RequiredTermsCondition" className="" type="checkbox"/>
                                    <span>컬리 이용약관 동의</span>
                                </label>
                                <span className="">(필수)</span>
                            </div>
                            <span className="">약관보기</span>
                        </div>
                        <div className="">
                            <div className="">
                                <label className="" for="RequiredTermsOfPrivacy">
                                    <input id="RequiredTermsOfPrivacy" className="" type="checkbox"/>
                                    <span>개인정보 수집∙이용</span>
                                </label>
                                <span className="">(필수)</span>
                            </div>
                            <span className=""></span>
                        </div>
                        <div className="">
                            <div className="">
                                <label className="" for="OptionTermsOfMktConsent">
                                    <input id="OptionTermsOfMktConsent" className="" type="checkbox"/>
                                    <span>이벤트 및 혜택정보 발송을 위한 수집·이용</span>
                                </label>
                                <span className="">(선택)</span>
                            </div>
                            <span>약관보기</span>
                        </div>
                        <div className="">
                            <div className="">
                                <label className="" for="SignupEventAll">
                                    <input id="SignupEventAll" className="" type="checkbox"/>
                                    <span>광고성 정보 수신</span></label><span className="">(선택)</span>
                            </div>
                            <div className="">
                                <label className="" for="OptionalTermsOfSms">
                                    <input id="OptionalTermsOfSms" className="" type="checkbox"/>
                                    <span>문자</span>
                                </label>
                                <label className="" for="OptionalTermsOfMailing">
                                    <input id="OptionalTermsOfMailing" className="" type="checkbox"/>
                                    <span>이메일</span>
                                </label>
                                <label className="" for="OptionalTermsOfKakao">
                                    <input id="OptionalTermsOfKakao" className="" type="checkbox"/>
                                    <span>카카오</span>
                                </label>
                            </div>
                        </div>
                        <div className="">
                            <div className="">
                                <label className="css-1aw9dzf ezpm6wd0" for="RequiredSignupAge">
                                    <input id="RequiredSignupAge" className="" type="checkbox"/>
                                <span>본인은 만 14세 이상입니다.</span></label><span className="">(필수)</span>
                            </div>
                        </div>
                    </div>
            </section>
        </>
    );
}

export default Join;