import React,{useState} from 'react';
import './css/Login.scss';
function Login() {


    const [formData,setFormData] = useState({
        userid:'',userpw:''
    });
    const adminId = 'test';
    const adminPassword = '1234';

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) =>(
            { ...prev, [name]: value }
        ));
    };
    const login = ()=>{
        let id = formData.userid;
        let pw = formData.userpw;
        if(id === adminId && pw === adminPassword){
            alert('로그인성공');
        }else{
            console.log(formData.userid);
            console.log(formData.userpw);
            console.log(adminId);
            console.log(adminPassword);
            alert('로그인에 실패하였습니다.');
            setFormData({userid:'',userpw:''});
        }
    }

    return (
        <>
            <div className="Login">
                <h2>로그인</h2>
                <form className="loginForm">
                    <div>
                        <div className="">
                            <div className="loginBox">
                                <input placeholder="아이디를 입력해주세요" className="loginInputBox" type="text" value={formData.userid} name="userid" onChange={handleChange}/></div>
                            </div>
                            <div className="loginBox">
                                <div className="">
                                    <input placeholder="비밀번호를 입력해주세요" className="loginInputBox" type="password" value={formData.userpw} name="userpw" onChange={handleChange}/>
                                </div>
                            </div>
                    </div>
                        <div className="forgotBox"><span className="forgot">아이디 찾기</span><span className="forgot">|</span><span className="forgot">비밀번호 찾기</span></div>
                        <div className="loginBtnBox">
                            <button className="loginBtn" type="button" onClick={login}>
                                <span className="">로그인</span>
                            </button>
                            <button className="joinBtn" type="button" >
                                <span className="">회원가입</span>
                            </button>
                        </div>
                        <div className="fastLoginBox">
                            <h2>간편 로그인</h2>
                            <button type="button" className="naverBtn">
                                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="14" viewBox="0 0 16 14" fill="none"><g clip-path="url(#clip0_24020_117094)"><path d="M10.52 7.49L5.28165 0H0.94165V14H5.49165V6.51L10.7183 14H15.0583V0H10.52V7.49Z" fill="var(--kpds_ldmw171v)"></path></g><defs><clipPath id="clip0_24020_117094"><rect width="14.1167" height="14" fill="var(--kpds_ldmw171v)" transform="translate(0.94165)"></rect></clipPath></defs></svg>
                                <p className="">네이버로계속하기</p>
                            </button>
                            <button type="button" className="kakaoBtn">
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="M3.16016 10.6264C3.16016 13.16 4.7886 15.3759 7.23126 16.6468L6.40501 19.82C6.37295 19.9152 6.39628 20.0208 6.46517 20.0924C6.51422 20.1395 6.5786 20.1659 6.64566 20.1667C6.70162 20.1634 6.75506 20.1417 6.79808 20.1048L10.3518 17.6289C10.8752 17.7064 11.4033 17.7464 11.9321 17.7486C16.7733 17.7486 20.704 14.5547 20.704 10.6181C20.704 6.68148 16.7733 3.5 11.9321 3.5C7.08687 3.5 3.16016 6.68973 3.16016 10.6264Z" fill="var(--kpds_ldmw171t)"></path></svg>
                                <p className="">카카오로 계속하기</p>
                            </button>
                        </div>
                    </form>
                </div>
        </>
    );
}

export default Login;