import React, {useState} from 'react';
import './css/Sub03.scss';
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {faShoppingCart} from "@fortawesome/free-solid-svg-icons";
import beauty1 from './images/sub03_product1.jpg';
import beauty2 from './images/sub03_product2.jpg';
import beauty3 from './images/sub03_product3.jpg';
import beauty4 from './images/sub03_product4.jpg';

function Sub03() {

    const [beauty] = useState([
        {
            beautyTitle : "파인애플 델몬트",
            beautyOriginalPrice : "12000",
            beautyPrice : "9000",
            beautyPercent : "30%",
            beautyImgSpace : beauty1
        },
        {
            beautyTitle : "바나나 스위트",
            beautyOriginalPrice : "321",
            beautyPrice : "1000",
            beautyPercent : "411",
            beautyImgSpace : beauty2
        },
        {
            beautyTitle : "사과 맛있어",
            beautyOriginalPrice : "123",
            beautyPrice : "321",
            beautyPercent : "132",
            beautyImgSpace : beauty3
        },
        {
            beautyTitle : "배 크다",
            beautyOriginalPrice : "123",
            beautyPercent : "321",
            beautyPrice : "231",
            beautyImgSpace : beauty4
        }
    ]);
    return (
        <>
            <article className="beautyProduct">
                <h4>🎀지금 인기 있는, 뷰티 베스트템</h4>
                <p>10만원 이상 구매 시 포티샤 샴푸 250mL 증정</p>
                <ul>
                    {beauty.map((item) => (
                        <li className="beauty" key={item.beautyTitle}>
                            <div className="imgSpace">
                                <img src={item.beautyImgSpace} alt=""/>
                            </div>
                            <div className="beautyCart"><button><FontAwesomeIcon icon={faShoppingCart} /> 담기</button></div>
                            <div className="beautyInfo">
                                <span className="beautyTitle">{item.beautyTitle}</span>
                                <p className="beautyOriginalPrice">{item.beautyOriginalPrice}</p>
                                <p className="beautyPercent">{item.beautyPercent}<span className="beautyPrice">{item.premiumPrice}</span></p>
                            </div>
                        </li>
                    ))}
                </ul>
            </article>
        </>
    );
}

export default Sub03;