import React from 'react';
import {Swiper, SwiperSlide} from 'swiper/react';
import { Navigation, Pagination, Autoplay, Scrollbar } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import './css/MainSlide.scss';
import banner1 from './images/kully_banner1.jpg';
import banner2 from './images/kully_banner2.jpg';
import banner3 from './images/kully_banner3.jpg';
import banner4 from './images/kully_banner4.jpg';
function MainSlide() {
    return (
        <>
            <Swiper
                modules={[Navigation, Pagination, Autoplay, Scrollbar]}
                navigation
                pagination={{ clickable: true }}
                autoplay={{ delay: 3000 }}
                scrollbar={{ draggable: true }}
                spaceBetween={0}
                slidesPerView={1}
                className="swiper-slide"
                //navigation={true} // navigation 버튼 활성화
                //pagination={{ clickable: true }} // pagination 활성화
                //autoplay={{ delay: 3000 }} // 자동 슬라이드 활성화
                //scrollbar={{ draggable: true }} // 스크롤바 활성화
                //spaceBetween={0} // 슬라이드 간격
                //slidesPerView={1} // 한 번에 보여줄 슬라이드 개수
                //className="swiper-slide" // 슬라이드 클래스명
            >
                <SwiperSlide>
                    <div className="slide">
                        <img src={banner1} alt="Slide 1" />
                    </div>
                </SwiperSlide>
                <SwiperSlide>
                    <div className="slide">
                        <img src={banner2} alt="Slide 2" />
                    </div>
                </SwiperSlide>
                <SwiperSlide>
                    <div className="slide">
                        <img src={banner3} alt="Slide 3" />
                    </div>
                </SwiperSlide>
                <SwiperSlide>
                    <div className="slide">
                        <img src={banner4} alt="Slide 4" />
                    </div>
                </SwiperSlide>
            </Swiper>
        </>
    );
}

export default MainSlide;